def format_row(item):
    """1 行分の表示文字列を返す。"""
    if item is not None:
        if item.get("name"):
            if item.get("count", 0) > 0:
                return f"{item['name']}: {item['count']}"
            else:
                return f"{item['name']}: -"
        else:
            return "(no name)"
    else:
        return "(empty)"

