def format_label(item):
    """商品ラベルの表示文字列を返す。"""
    if item is not None:
        if item.get("sku"):
            if item.get("stock", 0) > 0:
                return f"{item['sku']} (在庫あり)"
            else:
                return f"{item['sku']} (在庫なし)"
        else:
            return "(no sku)"
    else:
        return "(empty)"


def apply_discount(price, rate):
    """price に割引率 rate（0.0-1.0）を適用した金額を返す。

    例: apply_discount(1000, 0.2) は 20% 引きの 800 を返す。
    """
    return price - rate

