import unittest

from src.money import split_evenly, to_cents


class MoneyTest(unittest.TestCase):
    def test_to_cents_scales_by_hundred(self):
        self.assertEqual(to_cents(3), 300)

    def test_split_evenly_distributes_remainder(self):
